import java.awt.image.BufferedImage;import java.nio.file.*;import javax.imageio.ImageIO;
public final class GenerateMechTextures{
 static int pixel(int x,int y,int band){int[][] colors={{42,61,78},{187,201,195},{24,32,43},{164,119,66},{61,220,222}};int[] c=colors[band];int n=((x*1973^y*9277)&7)-3;boolean edge=(x%16==0||y%16==0);int a=0xff000000;for(int i=0;i<3;i++){int value=Math.min(255,Math.max(0,c[i]+n+(edge?band==4?22:12:0)));a|=value<<(16-i*8);}return a;}
 public static void main(String[] args)throws Exception{Path root=Path.of(args[0]);Path armor=root.resolve("models/armor/mana_mech_layer_1.png");Files.createDirectories(armor.getParent());BufferedImage img=new BufferedImage(256,256,BufferedImage.TYPE_INT_ARGB);for(int y=0;y<256;y++)for(int x=0;x<256;x++)img.setRGB(x,y,pixel(x,y,y<48?0:y<96?1:y<144?2:y<208?3:4));ImageIO.write(img,"png",armor.toFile());BufferedImage glow=new BufferedImage(256,256,BufferedImage.TYPE_INT_ARGB);for(int y=208;y<256;y++)for(int x=0;x<256;x++)glow.setRGB(x,y,0xffffffff);ImageIO.write(glow,"png",armor.getParent().resolve("mana_mech_glow.png").toFile());Path item=root.resolve("item");Files.createDirectories(item);String[] names={"metal","ceramic","gold","glow"};int[] indices={0,1,3,4};for(int k=0;k<names.length;k++){BufferedImage small=new BufferedImage(16,16,BufferedImage.TYPE_INT_ARGB);for(int y=0;y<16;y++)for(int x=0;x<16;x++)small.setRGB(x,y,pixel(x,y,indices[k]));ImageIO.write(small,"png",item.resolve("mech_"+names[k]+".png").toFile());}}
}
